def _data_to_text(data):
    """Reconstruct lines of text from pytesseract image_to_data dict,
    returning (text, lines_meta) where lines_meta is a list of
    [(word, conf), ...] per line matching text.splitlines() order."""
    n = len(data["text"])
    # Group words by (block, par, line)
    lines = {}
    order = []
    for i in range(n):
        word = data["text"][i].strip() if data["text"][i] else ""
        if not word:
            continue
        key = (data["block_num"][i], data["par_num"][i], data["line_num"][i])
        if key not in lines:
            lines[key] = []
            order.append(key)
        try:
            conf = int(float(data["conf"][i]))
        except (TypeError, ValueError):
            conf = -1
        lines[key].append((word, conf))

    text_lines = []
    meta_lines = []
    for key in order:
        words = lines[key]
        text_lines.append(" ".join(w for w, _ in words))
        meta_lines.append(words)
    return "\n".join(text_lines), meta_lines


