def ocr_date_crops(image_path):
    """Locate 'Date:'-like labels in the image, crop the area to the right of
    each, and OCR at high resolution with a digit-only whitelist.
    Returns a list of date strings (dd/mm/yyyy etc.) found."""
    img = Image.open(image_path)
    g = ImageOps.grayscale(img)
    locator_variants = [
        ImageOps.autocontrast(g),
        ImageOps.autocontrast(g).point(lambda p: 255 if p > 150 else 0),
        ImageOps.autocontrast(g).point(lambda p: 255 if p > 180 else 0),
    ]

    seen_boxes = []  # dedupe overlapping boxes
    for var in locator_variants:
        for psm in ["--psm 6", "--psm 4"]:
            try:
                data = pytesseract.image_to_data(
                    var, lang="eng", config=psm,
                    output_type=pytesseract.Output.DICT,
                )
            except Exception:
                continue
            for i, text in enumerate(data["text"]):
                if not text:
                    continue
                t = text.strip().lower()
                if t in _DATE_LABEL_WORDS:
                    x = data["left"][i]
                    y = data["top"][i]
                    w = data["width"][i]
                    h = data["height"][i]
                    if h <= 0 or w <= 0:
                        continue
                    box = (x, y, w, h)
                    # Dedupe close-by boxes
                    is_dup = any(
                        abs(bx - x) < 20 and abs(by - y) < 10
                        for bx, by, _bw, _bh in seen_boxes
                    )
                    if not is_dup:
                        seen_boxes.append(box)

    found = []
    for x, y, w, h in seen_boxes:
        crop_left = max(0, x + w)
        crop_right = min(img.width, x + w + max(400, h * 25))
        pad = max(4, int(h * 0.5))
        crop_top = max(0, y - pad)
        crop_bot = min(img.height, y + h + pad)
        if crop_right - crop_left < 30 or crop_bot - crop_top < 10:
            continue
        crop = img.crop((crop_left, crop_top, crop_right, crop_bot))
